// Public crew/community layouts use the existing catalog, membership and action hooks.
function publicMusicDate(created){return created?new Date(Number(created)*1000).toLocaleDateString('ko-KR',{month:'long',day:'numeric',timeZone:'Asia/Seoul'}):'';}
function crewPicture(c,cls='crew-hero-picture'){return '<span class="'+cls+'">'+(c.image_version?'<img src="/media/crew/'+esc(c.id)+'?v='+esc(c.image_version)+'" alt="'+esc(c.name)+'">':icon('users'))+'</span>';}
function crewHeroHTML(c,m){return '<header class="crew-hero">'+crewPicture(c)+'<div class="crew-hero-copy"><span class="eyebrow">'+(m?'MY CREW':'MUSIC CREW')+'</span><h1>'+esc(c.name)+'</h1><p>LV '+number(c.level)+' · '+number(c.members)+'명이 함께해요</p><p class="crew-hero-description">'+esc(c.description||'음악과 이야기가 함께하는 우리 크루')+'</p></div><div class="crew-hero-actions">'+(m?'<span class="small-button">'+icon('check')+' 가입한 크루</span>':'')+'<a class="small-button" href="#crew/'+esc(c.id)+'?tab=members">'+icon('users')+' '+number(c.members)+'명</a><a class="text-link" href="#community/crews?browse=1">크루 둘러보기 '+icon('chevron')+'</a></div></header>';}
function crewMusicRows(tracks){return tracks.length?songTable(tracks):'<p class="social-empty">조건에 맞는 음악이 없어요. 검색어나 필터를 바꿔보세요.</p>';}
function crewHomeLayout(d,intro){
 const c=d.crew,tracks=d.tracks||[],members=d.members||[],gs=[...new Set(tracks.map(t=>t.genre).filter(Boolean))].sort();
 return '<div class="crew-home-layout"><div class="crew-home-main">'+(d.membership?'<a class="crew-chat-entry" href="#dm/crew/'+esc(c.id)+'">'+icon('message')+'<span><strong>크루 채팅방 들어가기</strong><small>크루원들과 음악과 이야기를 나눠보세요.</small></span>'+icon('chevron')+'</a>':'<p class="social-empty">크루에 가입하면 함께 대화할 수 있어요.</p>')+
 '<form id="crew-music-filter" class="crew-music-filter"><label class="crew-music-search">'+icon('search')+'<input name="q" type="search" maxlength="100" aria-label="크루 음악 검색" placeholder="크루 곡에서 검색하기…"></label><select name="sort" aria-label="크루 음악 정렬"><option value="recent">최신순</option><option value="plays">재생순</option><option value="likes">좋아요순</option></select><select name="genre" aria-label="크루 음악 장르"><option value="">모든 장르</option>'+gs.map(g=>'<option>'+esc(g)+'</option>').join('')+'</select><select name="period" aria-label="공개 기간"><option value="all">전체 기간</option><option value="week">최근 7일</option><option value="month">최근 30일</option></select></form><div class="section-heading"><h2>크루의 최신 음악</h2><span id="crew-music-count" role="status">'+number(tracks.length)+'곡</span></div><div id="crew-music-results">'+(tracks.length?crewMusicRows(tracks):'<p class="social-empty">아직 공개한 크루 음악이 없어요.</p>')+'</div><p class="field-help">최근 공개된 최대 60곡에서 검색하고 정렬해요.</p></div><aside class="social-side-column"><section class="social-side-card"><div class="section-heading"><h2>크루 소개</h2><a href="#crew/'+esc(c.id)+'?tab=about">더보기 '+icon('chevron')+'</a></div>'+intro+'</section><section class="social-side-card"><div class="section-heading"><h2>크루원 <small>'+number(c.members)+'명</small></h2><a href="#crew/'+esc(c.id)+'?tab=members">전체보기 '+icon('chevron')+'</a></div><div class="crew-member-preview">'+members.slice(0,5).map(p=>'<a href="#producer/'+esc(p.id)+'">'+portrait(p,'producer')+'<strong>'+esc(p.name)+'</strong><small>'+esc(crewRoleLabels[p.role]||'크루원')+'</small></a>').join('')+'</div></section><section class="social-side-card"><h2>최근 공개 활동</h2><div class="crew-activity">'+(tracks.length?tracks.slice(0,4).map(t=>'<a href="#song/'+esc(t.id)+'">'+cover(t,'mini-cover')+'<span><strong>'+esc(t.producer)+'</strong>님의 '+(t.kind==='cover'?'커버':'새 음악')+'<b>'+esc(t.title)+'</b><small>'+publicMusicDate(t.created)+'</small></span></a>').join(''):'<p class="field-help">새로 공개한 음악이 여기에 표시돼요.</p>')+'</div></section></aside></div>';
}
function filterCrewMusic(tracks,{q='',sort='recent',genre='',period='all'}={},now=Date.now()){
 const term=q.trim().toLocaleLowerCase(),cutoff=period==='week'?now/1000-7*86400:period==='month'?now/1000-30*86400:0;
 return tracks.filter(t=>(!genre||t.genre===genre)&&(!cutoff||Number(t.created)>=cutoff)&&(!term||[t.title,t.producer,t.artist].some(v=>String(v||'').toLocaleLowerCase().includes(term)))).sort((a,b)=>(sort==='plays'?Number(b.plays||0)-Number(a.plays||0):sort==='likes'?Number(b.likes||0)-Number(a.likes||0):0)||Number(b.created||0)-Number(a.created||0));
}
function bindCrewHome(view){
 const form=$('#crew-music-filter');if(!form)return;
 const update=()=>{const value=n=>form.elements[n].value,items=filterCrewMusic(view.tracks,{q:value('q'),sort:value('sort'),genre:value('genre'),period:value('period')});$('#crew-music-results').innerHTML=crewMusicRows(items);$('#crew-music-count').textContent=number(items.length)+'곡';routeTracks=items;};
 form.onsubmit=e=>{e.preventDefault();update();};form.addEventListener('input',update);form.addEventListener('change',update);
}
function communityLandingHTML(tracks,data,tab='all',{open=false,login=false}={}){
 const tags=[['커버','#community/covers'],['듀엣','#community/duets'],['크루','#community/crews?browse=1'],['플레이리스트','#collections']];
 const genreCounts=new Map();tracks.forEach(t=>{if(t.genre)genreCounts.set(t.genre,(genreCounts.get(t.genre)||0)+1);});
 const genreTags=[...genreCounts].sort((a,b)=>b[1]-a[1]).slice(0,4).map(([g])=>[g,'#discover/genres?g='+encodeURIComponent(g)]);
 const subtitle=tab==='covers'?'새로 공개된 커버':tab==='duets'?(open?'함께 부를 목소리를 기다려요':'함께 완성한 듀엣'):tab==='following'?'팔로잉의 새 음악':tab==='originals'?'새로 공개된 제작곡':'';
 const feed=login?gate():!data?'<div class="route-loading" role="status">새 음악을 불러오는 중…</div>':tracks.length?'<div class="music-feed">'+tracks.map(communityConceptCard).join('')+'</div>':empty('아직 공개된 음악이 없어요.','새로운 음악과 목소리를 기다리고 있어요.','#karaoke','부를 곡 찾기');
 return '<div class="community-landing-layout community-redesign"><div class="community-feed-column"><header class="community-masthead"><div class="community-landing-heading">'+heading('커뮤니티','좋은 음악을 듣고, 담고, 함께 만들어가요.')+'<div class="community-hero-note" aria-hidden="true"><span>Music<br>brings us closer.</span><p>좋은 음악이<br>좋은 사람들을 더 가깝게.</p></div></div>'+communityNavigation(tab)+'</header>'+(subtitle?'<div class="community-feed-heading"><h2>'+subtitle+'</h2>'+(tab==='duets'?'<nav aria-label="듀엣 종류"><a href="#community/duets" '+(!open?'aria-current="page"':'')+'>듀엣 감상</a><a href="#community/duets?open=1" '+(open?'aria-current="page"':'')+'>참여 대기</a></nav>':'')+'</div>':'')+feed+'</div><aside class="social-side-column community-side-column"><div id="community-crew-preview" class="community-side-crews"><p class="social-side-card" role="status">크루를 불러오는 중…</p></div><section class="social-side-card"><h2>음악으로 이어지는 관심사</h2><p class="field-help">좋아하는 장르로 더 찾아보세요.</p><nav class="community-tag-cloud" aria-label="커뮤니티 음악 탐색">'+[...tags,...genreTags].map(([label,href])=>'<a href="'+esc(href)+'">#'+esc(label)+'</a>').join('')+'</nav></section><section class="community-side-invitation"><span class="community-orbit" aria-hidden="true"></span><p>당신의 음악이<br><strong>누군가의 하루를 바꿀 수 있어요.</strong></p><a href="#upload">음원 올리기 '+icon('chevron')+'</a></section><section class="social-side-card community-cover-rank-links"><h2>커버 랭킹</h2><nav class="community-tag-cloud" aria-label="커버 랭킹 기간">'+[['today','오늘'],['week','이번 주'],['month','이달'],['all','명예의 전당']].map(([key,label])=>'<a href="#community/rankings?period='+key+'">'+label+'</a>').join('')+'</nav></section></aside></div>';
}

function communityCrewSidebarHTML(d){
 const crews=[...(d.crews||[])].sort((a,b)=>Number(b.xp||0)-Number(a.xp||0)).slice(0,5);
 return '<section class="social-side-card"><div class="section-heading"><h2>함께하는 크루</h2><a href="#community/crews?browse=1">더보기 '+icon('chevron')+'</a></div><div class="community-crew-circles">'+crews.map(c=>'<a href="#crew/'+esc(c.id)+'">'+crewPicture(c,'crew-circle')+'<strong>'+esc(c.name)+'</strong><small>'+number(c.members)+'명</small></a>').join('')+(crews.length?'':'<p class="field-help">첫 크루를 만나보세요.</p>')+'</div><div class="community-crew-invite"><span>'+icon('mic')+'</span><h3>좋은 음악은,<br>좋은 사람들과 더 멀리.</h3><p>크루와 함께 더 특별한 음악을 만들어요.</p><a class="small-button" href="#community/crews?browse=1">크루 둘러보기 '+icon('arrow')+'</a></div></section>'+crewRankingSidebarHTML(d.rankings);
}
function crewRankingSidebarHTML(rankings){
 const items=[...(rankings||[])].sort((a,b)=>Number(b.level||1)-Number(a.level||1)||Number(b.xp||0)-Number(a.xp||0)).slice(0,5);
 return '<section class="social-side-card crew-ranking-card"><div class="section-heading"><h2>크루 랭킹</h2><span class="crew-ranking-label">TOP 5</span></div><p class="crew-ranking-rule">레벨순 · 같은 레벨은 누적 XP순</p>'+(items.length?'<ol class="community-crew-ranking">'+items.map((c,i)=>'<li><a href="#crew/'+esc(c.id)+'"><span class="crew-rank-position">'+(i+1)+'<span class="sr-only">위</span></span>'+crewPicture(c,'crew-rank-picture')+'<span class="crew-rank-copy"><strong>'+esc(c.name)+'</strong><small>'+number(c.members)+'명</small></span><span class="crew-rank-stats"><b>LV '+number(c.level)+'</b><small>'+number(c.xp)+' XP</small></span></a></li>').join('')+'</ol>':'<p class="field-help">'+(rankings?'아직 등록된 크루가 없어요.':'크루 랭킹을 불러오는 중…')+'</p>')+'</section>';
}
